import { InvoiceLineItems } from '../../invoice/entities/invoice.entity.js';
import {
    aggregationInterval,
    aggregationMethod,
    countBasedUnits,
    overageAllowedEnum,
    roundingEnum,
} from '../../dimensions/dto/create-dimension.dto.js';
import { ValidBillingCycles } from '../dto/createOffering.dto.js';
import { SupportedCurrencies } from '../dto/SupportedCurrencies.js';
import { Offering } from './offeringPackage.entity.js';
import { FreeDimensionOnInvoice } from '../../setting/dto/FreeDimensionOnInvoice.js';
import { OfferingType } from './OfferingType.js';

jest.mock('../../analytics/analytics.service', () => ({
    AnalyticsService: { getExchangeRate: jest.fn(() => 0.91) },
}));

const dim = (extra: any) => ({
    aggregationInterval: aggregationInterval.month,
    aggregationMethod: aggregationMethod.sum,
    dimensionName: 'D',
    rounding: roundingEnum.floor,
    consumptionUnit: { unit: countBasedUnits['count-based'], type: 'count' },
    dimensionId: '123',
    usageIncrement: '1',
    ...extra,
});

async function run(dimension: any, usageValue: string, freeSetting = FreeDimensionOnInvoice.show) {
    const offering: any = {
        offeringId: '1', offeringName: 'off', offeringType: OfferingType.usageBased,
        currency: SupportedCurrencies.USD, billingCycle: ValidBillingCycles.monthly,
        dimensions: [dimension],
    };
    const usageOverrides = [{ offeringId: '1', dimensionId: '123', usage: [{ value: usageValue, startTime: '2024-01-01T00:00:00Z', endTime: '2024-01-02T00:00:00Z' }] }];
    const inst = Offering.getInstance(offering, 'c', 'b', undefined, { freeDimensionOnInvoice: freeSetting } as any, undefined, undefined, undefined, usageOverrides as any);
    const li = new InvoiceLineItems();
    await Offering.getLineItemsForUsage({
        startDate: new Date('2024-01-01'), endDate: new Date('2024-01-31'),
        lineItems: li, negative: false, businessID: 'b', customerId: 'c',
        customerService: undefined as any, dimensions: [dimension], offeringInstance: inst,
    });
    return li.getLineItems();
}

describe('allowance/overage/free-dimension', () => {
    test('finite exhausted allowance, overage allowed -> charge only overage', async () => {
        const r = await run(dim({ consumptionPrice: '1', usageEntitlement: 100, overageAllowed: overageAllowedEnum.true }), '150');
        expect(r).toHaveLength(1);
        expect(r[0].quantity).toBe(50);
        expect(r[0].unitCost).toBe(1);
    });
    test('unexhausted allowance -> no line', async () => {
        const r = await run(dim({ consumptionPrice: '1', usageEntitlement: 100, overageAllowed: overageAllowedEnum.true }), '80');
        expect(r).toHaveLength(0);
    });
    test('unlimited allowance -> no line', async () => {
        const r = await run(dim({ consumptionPrice: '1', usageEntitlement: 'inf', overageAllowed: overageAllowedEnum.true }), '80');
        expect(r).toHaveLength(0);
    });
    test('overage forbidden -> no line even if exhausted', async () => {
        const r = await run(dim({ consumptionPrice: '1', usageEntitlement: 100, overageAllowed: overageAllowedEnum.false }), '150');
        expect(r).toHaveLength(0);
    });
    test('no allowance priced -> charge full', async () => {
        const r = await run(dim({ consumptionPrice: '2' }), '10');
        expect(r).toHaveLength(1);
        expect(r[0].quantity).toBe(10);
    });
    test('priced zero -> line shown when settings show', async () => {
        const r = await run(dim({ consumptionPrice: '0' }), '10', FreeDimensionOnInvoice.show);
        expect(r).toHaveLength(1);
        expect(r[0].unitCost).toBe(0);
        expect(r[0].quantity).toBe(10);
    });
    test('priced zero -> hidden when settings hide', async () => {
        const r = await run(dim({ consumptionPrice: '0' }), '10', FreeDimensionOnInvoice.hide);
        expect(r).toHaveLength(0);
    });
    test('priced positive zero usage -> no line (owes nothing)', async () => {
        const r = await run(dim({ consumptionPrice: '5' }), '0');
        expect(r).toHaveLength(0);
    });
});
EOF
